import { test, expect } from '@playwright/test';

test.describe('Tab Navigation with URL Hash', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to a page with tabs
    await page.goto('about:blank');

    // Create a simple HTML page with tabs that update URL hash
    await page.setContent(`
      <!DOCTYPE html>
      <html>
      <head>
        <style>
          .tabs {
            display: flex;
            gap: 10px;
            margin-bottom: 20px;
            border-bottom: 2px solid #ccc;
          }
          .tab-button {
            padding: 10px 20px;
            background: none;
            border: none;
            cursor: pointer;
            font-size: 16px;
            border-bottom: 3px solid transparent;
          }
          .tab-button.active {
            border-bottom-color: #007bff;
            color: #007bff;
          }
          .tab-content {
            display: none;
          }
          .tab-content.active {
            display: block;
          }
        </style>
      </head>
      <body>
        <div class="tabs">
          <button class="tab-button active" data-tab="home">Home</button>
          <button class="tab-button" data-tab="about">About</button>
          <button class="tab-button" data-tab="contact">Contact</button>
        </div>

        <div id="home" class="tab-content active">
          <h2>Home Tab</h2>
          <p>Welcome to the home tab</p>
        </div>
        <div id="about" class="tab-content">
          <h2>About Tab</h2>
          <p>This is the about tab</p>
        </div>
        <div id="contact" class="tab-content">
          <h2>Contact Tab</h2>
          <p>This is the contact tab</p>
        </div>

        <script>
          function updateTabContent(tabName) {
            // Hide all tabs
            document.querySelectorAll('.tab-content').forEach(tab => {
              tab.classList.remove('active');
            });
            document.querySelectorAll('.tab-button').forEach(btn => {
              btn.classList.remove('active');
            });

            // Show selected tab
            const selectedTab = document.getElementById(tabName);
            if (selectedTab) {
              selectedTab.classList.add('active');
            }

            // Update active button
            const activeBtn = document.querySelector(\`[data-tab="\${tabName}"]\`);
            if (activeBtn) {
              activeBtn.classList.add('active');
            }

            // Update URL hash
            window.location.hash = tabName;
          }

          // Handle tab button clicks
          document.querySelectorAll('.tab-button').forEach(button => {
            button.addEventListener('click', (e) => {
              const tabName = e.target.getAttribute('data-tab');
              updateTabContent(tabName);
            });
          });

          // Handle hash change from URL
          window.addEventListener('hashchange', () => {
            const hash = window.location.hash.slice(1);
            if (hash) {
              updateTabContent(hash);
            }
          });

          // Initialize based on current hash
          const initialHash = window.location.hash.slice(1);
          if (initialHash) {
            updateTabContent(initialHash);
          }
        </script>
      </body>
      </html>
    `);
  });

  test('should update URL hash when clicking on a tab', async ({ page }) => {
    // Click on the About tab
    await page.getByRole('button', { name: 'About' }).click();

    // Verify the URL hash is updated
    expect(page.url()).toContain('#about');

    // Verify the About tab content is displayed
    await expect(page.getByRole('heading', { name: 'About Tab' })).toBeVisible();
  });

  test('should update URL hash when clicking on different tabs sequentially', async ({ page }) => {
    // Click on Contact tab
    await page.getByRole('button', { name: 'Contact' }).click();
    expect(page.url()).toContain('#contact');
    await expect(page.getByRole('heading', { name: 'Contact Tab' })).toBeVisible();

    // Click on About tab
    await page.getByRole('button', { name: 'About' }).click();
    expect(page.url()).toContain('#about');
    await expect(page.getByRole('heading', { name: 'About Tab' })).toBeVisible();

    // Click on Home tab
    await page.getByRole('button', { name: 'Home' }).click();
    expect(page.url()).toContain('#home');
    await expect(page.getByRole('heading', { name: 'Home Tab' })).toBeVisible();
  });

  test('should navigate to tab when URL hash is set directly', async ({ page }) => {
    // Navigate directly to a tab using hash
    await page.goto('about:blank#about');

    // Wait for content to load
    await page.waitForLoadState('networkidle');

    // Verify the correct tab content is displayed
    await expect(page.getByRole('heading', { name: 'About Tab' })).toBeVisible();

    // Verify the About button is marked as active
    const aboutButton = page.getByRole('button', { name: 'About' });
    await expect(aboutButton).toHaveClass(/active/);
  });

  test('should maintain tab state when navigating back and forward', async ({ page }) => {
    // Click on About tab
    await page.getByRole('button', { name: 'About' }).click();
    expect(page.url()).toContain('#about');

    // Click on Contact tab
    await page.getByRole('button', { name: 'Contact' }).click();
    expect(page.url()).toContain('#contact');

    // Navigate back
    await page.goBack();
    expect(page.url()).toContain('#about');
    await expect(page.getByRole('heading', { name: 'About Tab' })).toBeVisible();

    // Navigate forward
    await page.goForward();
    expect(page.url()).toContain('#contact');
    await expect(page.getByRole('heading', { name: 'Contact Tab' })).toBeVisible();
  });

  test('should display correct tab content with proper styling', async ({ page }) => {
    // Initially Home tab should be active
    const homeButton = page.getByRole('button', { name: 'Home' });
    await expect(homeButton).toHaveClass(/active/);

    // Click About tab
    const aboutButton = page.getByRole('button', { name: 'About' });
    await aboutButton.click();

    // Verify About button is now active
    await expect(aboutButton).toHaveClass(/active/);

    // Verify Home button is no longer active
    await expect(homeButton).not.toHaveClass(/active/);

    // Verify correct content is displayed
    await expect(page.getByText('This is the about tab')).toBeVisible();
  });
});
